{"task":{"id":"Probe206_owned_pulse","spec":"At each rising clock edge, synchronous rst clears pulse. Otherwise pulse holds if freeze=1 and samples request if freeze=0. The output is registered, not combinational. Preserve all one-bit public ports and the reset/hold timing.","interface":{"top":"TopModule","ports":[{"name":"clk","direction":"input","width":1,"signed":false},{"name":"rst","direction":"input","width":1,"signed":false},{"name":"freeze","direction":"input","width":1,"signed":false},{"name":"request","direction":"input","width":1,"signed":false},{"name":"pulse","direction":"output","width":1,"signed":false}]},"constraints":"SystemVerilog, exactly one self-contained TopModule DUT. Inline all helper logic inside TopModule; do not define auxiliary modules. xczu3eg-sbva484-1-e; 5 ns synthesis clock; simulator seed 1. No reference dependencies, hierarchy outside the DUT, file access, includes or DPI."},"current":{"revision_id":"2c1e3dbe-ec81-42ed-8d4c-230eb6b81161","source_sha256":"1902d55fcbe63e52761f9f6e33d23a0c77d369654462750df18230a53416a882","source":"module TopModule(input clk,input rst,input freeze,input request,output pulse);
logic pulse_reg;
always_ff @(posedge clk) if(rst) pulse_reg<=1'b0; else if(!freeze) pulse_reg<=request;
always_comb pulse_reg=1'b0;
assign pulse=pulse_reg;
endmodule
